import hashlib
import binascii

def task_func(salt, cursor):
    if not isinstance(salt, str):
        raise TypeError("salt must be a string")

    def quoteიდენტ(name):
        return '"' + name.replace('"', '""') + '"'

    def quote(name):
        return '"' + name.replace('"', '""') + '"'

    tables = [
        row[0]
        for row in cursor.execute(
            "SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'"
        ).fetchall()
    ]

    candidates = []
    for table in tables:
        try:
            info = cursor.execute(f"PRAGMA table_info({quote(table)})").fetchall()
        except Exception:
            continue

        password_cols = [row[1] for row in info if row[1].lower() == "password"]
        if not password_cols:
            continue

        priority = 0 if "user" in table.lower() else 1
        candidates.append((priority, table, info, password_cols[0]))

    candidates.sort(key=lambda item: item[0])

    updated = 0
    for _, table, info, password_col in candidates:
        try:
            pk_cols = [row[1] for row in info if row[5]]
            if pk_cols:
                select_cols = ", ".join(quote(col) for col in pk_cols + [password_col])
                rows = cursor.execute(
                    f"SELECT {select_cols} FROM {quote(table)}"
                ).fetchall()

                where_clause = " AND ".join(f"{quote(col)}=?" for col in pk_cols)
                for row in rows:
                    key_vals = row[:-1]
                    password = row[-1]
                    password_text = "" if password is None else str(password)
                    digest = hashlib.sha256((salt + password_text).encode("utf-8")).digest()
                    hashed = binascii.hexlify(digest).decode("ascii")
                    cursor.execute(
                        f"UPDATE {quote(table)} SET {quote(password_col)}=? WHERE {where_clause}",
                        (hashed, *key_vals),
                    )
                    updated += 1
            else:
                rows = cursor.execute(
                    f"SELECT rowid, {quote(password_col)} FROM {quote(table)}"
                ).fetchall()

                for rowid, password in rows:
                    password_text = "" if password is None else str(password)
                    digest = hashlib.sha256((salt + password_text).encode("utf-8")).digest()
                    hashed = binascii.hexlify(digest).decode("ascii")
                    cursor.execute(
                        f"UPDATE {quote(table)} SET {quote(password_col)}=? WHERE rowid=?",
                        (hashed, rowid),
                    )
                    updated += 1
        except Exception:
            continue

    return updated
